INSERT INTO drilling_reports (id, well_id, report_date, depth_m, formation, event_type, notes, source_document) VALUES ('8c2f3e33-1d4f-5fe5-b490-19938d0ba9ad', 'ece7e8d1-15bc-54da-9006-9611150fd796', '2019-01-06T00:00:00+00:00', 3126.2, 'Barail Coal-Shale Fm.', 'kick', 'Severe formation gas kick encountered at 3126 m MD while penetrating Barail Coal-Shale sequence. Pit gain 24 bbl within 4 minutes. Well shut-in on BOP. SIDPP 480 psi, SICP 590 psi. Circulated out influx using Wait and Weight method.', 'DDR_IND-NWIS-18_3126m_ASSAM.pdf') ON CONFLICT (id) DO NOTHING;
INSERT INTO drilling_reports (id, well_id, report_date, depth_m, formation, event_type, notes, source_document) VALUES ('e103391a-daa9-538b-9ce7-5990eda5e2ae', 'ece7e8d1-15bc-54da-9006-9611150fd796', '2020-10-09T00:00:00+00:00', 3302.7, 'Barail Coal-Shale Fm.', 'drilling_problem', 'Severe torsional stick-slip vibration and chert stringers at 3303 m MD. Downhole vibration sensor triggered red alarm. Pulled bit; found 3 chipped PDC cutters and worn stabilizer blades.', 'DDR_IND-NWIS-18_3302m_ASSAM.pdf') ON CONFLICT (id) DO NOTHING;
INSERT INTO drilling_reports (id, well_id, report_date, depth_m, formation, event_type, notes, source_document) VALUES ('235224c9-a630-5a49-ab12-4f9f7ae7df50', 'ece7e8d1-15bc-54da-9006-9611150fd796', '2021-08-14T00:00:00+00:00', 3426.6, 'Barail Main Sandstone Fm.', 'cementing', 'Encountered weak bonding across Barail gas zone during 5 liner cement job at 3427 m MD. Cement bond log (CBL) showed channeling. Performed remedial squeeze cementation through retainer.', 'DDR_IND-NWIS-18_3426m_ASSAM.pdf') ON CONFLICT (id) DO NOTHING;
INSERT INTO drilling_reports (id, well_id, report_date, depth_m, formation, event_type, notes, source_document) VALUES ('11d289e3-24b2-5fe2-921c-a3bf4ce53415', 'ece7e8d1-15bc-54da-9006-9611150fd796', '2022-04-15T00:00:00+00:00', 3467.2, 'Barail Main Sandstone Fm.', 'normal', 'Core barrel trip recovered 9m of Barail Main Sandstone reservoir core from 3511m to 3467 m MD. 100% recovery. Good oil shows and fluorescence.', 'DDR_IND-NWIS-18_3467m_ASSAM.pdf') ON CONFLICT (id) DO NOTHING;
